// 适配器模式 - 统一不同数据源的接口

/**
 * 数据适配器基类
 * 定义统一的接口规范
 */
class DataAdapter {
  constructor(sourceType) {
    this.sourceType = sourceType;
    this.cache = new Map();
  }

  /**
   * 获取数据 - 子类必须实现
   * @param {string} key - 数据标识
   * @returns {Promise<any>}
   */
  async fetch(key) {
    throw new Error('子类必须实现 fetch 方法');
  }

  /**
   * 转换数据格式 - 子类必须实现
   * @param {any} rawData - 原始数据
   * @returns {any}
   */
  transform(rawData) {
    throw new Error('子类必须实现 transform 方法');
  }

  /**
   * 缓存数据
   * @param {string} key 
   * @param {any} data 
   * @param {number} ttl - 缓存时间(毫秒)
   */
  setCache(key, data, ttl = 60000) {
    this.cache.set(key, {
      data,
      expire: Date.now() + ttl
    });
  }

  /**
   * 获取缓存
   * @param {string} key 
   * @returns {any|null}
   */
  getCache(key) {
    const cached = this.cache.get(key);
    if (cached && cached.expire > Date.now()) {
      return cached.data;
    }
    this.cache.delete(key);
    return null;
  }

  /**
   * 统一的获取数据入口
   * @param {string} key 
   * @returns {Promise<any>}
   */
  async getData(key) {
    // 先查缓存
    const cached = this.getCache(key);
    if (cached) return cached;

    // 获取并转换数据
    const rawData = await this.fetch(key);
    const transformedData = this.transform(rawData);

    // 设置缓存
    this.setCache(key, transformedData);

    return transformedData;
  }
}

