    return {
      id: rawData.id || rawData._id,
      name: rawData.name || rawData.title,
      value: rawData.value || rawData.data,
      metadata: {
        source: this.sourceType,
        timestamp: new Date().toISOString(),
        raw: rawData
      }
    };
  }

  delay(ms) {
    return new Promise(resolve => setTimeout(resolve, ms));
  }
}

